prompt --application/shared_components/automations/enviar_email
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(365567827205050923)
,p_name=>'Enviar Email'
,p_static_id=>'enviar-email'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=0;BYMINUTE=30'
,p_polling_status=>'ACTIVE'
,p_result_type=>'ALWAYS'
,p_use_local_sync_table=>false
,p_include_rowid_column=>false
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(365568110558050926)
,p_automation_id=>wwv_flow_imp.id(365567827205050923)
,p_name=>'Enviar Email'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR c_aniversarios IS',
'        SELECT nom_aniv,',
'               email,',
'               dat_aniv,',
'               dat_vinculo',
'        FROM aniv_aniversarios',
'        WHERE TO_CHAR(dat_aniv, ''MMDD'') = TO_CHAR(SYSDATE, ''MMDD'')',
'            OR TO_CHAR(dat_vinculo, ''MMDD'') = TO_CHAR(SYSDATE, ''MMDD'');',
'',
'    v_assunto   VARCHAR2(200);',
'    v_mensagem  VARCHAR2(4000);',
'    v_html_esp  VARCHAR2(2000);',
'',
'    v_blob      BLOB;',
'    v_filename  VARCHAR2(200);',
'    v_mimetype  VARCHAR2(200);',
'',
'    v_anos      NUMBER;',
'    v_anos_2    VARCHAR2(200);',
'',
'    email_id    NUMBER;',
'BEGIN',
'    FOR r IN c_aniversarios LOOP',
'        ',
unistr('        -- Verifica se \00E9 anivers\00E1rio de vida'),
'        IF TO_CHAR(r.dat_aniv, ''MMDD'') = TO_CHAR(SYSDATE, ''MMDD'') THEN',
unistr('            v_assunto  := ''Feliz anivers\00E1rio!'';'),
'            v_html_esp :=',
'                ''<p style="font-size:18px; font-weight:bold; margin-bottom:20px;">'' ||',
unistr('                ''Feliz anivers\00E1rio! Que seu dia seja repleto de alegria, sa\00FAde e muitas conquistas.'' ||'),
'                ''</p>'';',
'',
'            BEGIN',
'                SELECT imagem, filename, mimetype',
'                INTO v_blob, v_filename, v_mimetype',
'                FROM aniv_mensagem',
'                WHERE nome = r.nom_aniv;',
'                ',
'                v_mensagem := ''',
'                    <html>',
'                        <body style="text-align:center; font-family: Arial, sans-serif;">'' ||',
'                            v_html_esp ||',
'',
'                            ''<table width="350" cellpadding="0" cellspacing="0" border="0" align="center">',
'                                <tr>',
'                                    <td align="center">',
'                                        <img src="cid:foto_aniversario" style="display:block;" width="350" border="0">',
'                                    </td>',
'                                </tr>',
'                            </table>',
'',
'                            <br><br>',
'',
'                            <p style="font-size:14px; color:#003A6B; line-height:20px; text-align:center;">',
unistr('                                Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG/DGER<br>'),
'                                Diretoria-Geral<br>',
'                                Bloco 10/Sala 17<br><br>',
'                            </p>',
'                        </body>',
'                    </html>'';',
'',
unistr('                -- ENVIAR EMAIL de anivers\00E1rio de vida'),
'                email_id := APEX_MAIL.SEND(',
'                    p_to       => r.email,',
'                    p_from     => ''asqualog@senado.leg.br'',',
'                    p_subj     => v_assunto,',
unistr('                    p_body     => ''Seu email n\00E3o suporta HTML.'','),
'                    p_body_html => v_mensagem',
'                );',
'                ',
'                APEX_MAIL.ADD_ATTACHMENT(',
'                    p_mail_id    => email_id,',
'                    p_attachment => v_blob,',
'                    p_filename   => v_filename,',
'                    p_mime_type  => v_mimetype,',
'                    p_content_id => ''foto_aniversario'');',
'                    ',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
unistr('                    NULL; -- Ou tratar de outra forma se n\00E3o encontrar a imagem'),
'            END;',
'        END IF;',
'',
unistr('        -- Verifica se \00E9 anivers\00E1rio de v\00EDnculo (pode ser no mesmo dia)'),
'        IF TO_CHAR(r.dat_vinculo, ''MMDD'') = TO_CHAR(SYSDATE, ''MMDD'') THEN',
'            v_anos := FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), TRUNC(r.dat_vinculo)) / 12);',
'            v_anos_2 := v_anos || '' Anos'';',
'',
unistr('            v_assunto  := ''Parab\00E9ns pelos seus '' || v_anos || '' anos de v\00EDnculo!'';'),
'            v_html_esp :=',
'                ''<p style="font-size:18px; font-weight:bold; margin-bottom:20px;">'' ||',
unistr('                ''Parab\00E9ns pelos seus '' || v_anos || '' anos de v\00EDnculo conosco! Seu trabalho e dedica\00E7\00E3o fazem a diferen\00E7a.'' ||'),
'                ''</p>'';',
'',
'            BEGIN',
'                SELECT imagem, filename, mimetype',
'                INTO v_blob, v_filename, v_mimetype',
'                FROM aniv_mensagem',
'                WHERE nome = v_anos_2;',
'',
'                v_mensagem := ''',
'                    <html>',
'                        <body style="text-align:center; font-family: Arial, sans-serif;">'' ||',
'                            v_html_esp ||',
'',
'                            ''<table width="350" cellpadding="0" cellspacing="0" border="0" align="center">',
'                                <tr>',
'                                    <td align="center">',
'                                        <img src="cid:foto_aniversario" style="display:block;" width="350" border="0">',
'                                    </td>',
'                                </tr>',
'                            </table>',
'',
'                            <br><br>',
'',
'                            <p style="font-size:14px; color:#003A6B; line-height:20px; text-align:center;">',
unistr('                                Assessoria de Qualidade de Atendimento e Log\00EDstica \2013 ASQUALOG/DGER<br>'),
'                                Diretoria-Geral<br>',
'                                Bloco 10/Sala 17<br><br>',
'                            </p>',
'                        </body>',
'                    </html>'';',
'',
unistr('                -- ENVIAR EMAIL de anivers\00E1rio de v\00EDnculo'),
'                email_id := APEX_MAIL.SEND(',
'                    p_to       => r.email,',
'                    p_from     => ''asqualog@senado.leg.br'',',
'                    p_subj     => v_assunto,',
unistr('                    p_body     => ''Seu email n\00E3o suporta HTML.'','),
'                    p_body_html => v_mensagem',
'                );',
'                ',
'                APEX_MAIL.ADD_ATTACHMENT(',
'                    p_mail_id    => email_id,',
'                    p_attachment => v_blob,',
'                    p_filename   => v_filename,',
'                    p_mime_type  => v_mimetype,',
'                    p_content_id => ''foto_aniversario'');',
'                    ',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
unistr('                    NULL; -- Ou tratar de outra forma se n\00E3o encontrar a imagem'),
'            END;',
'        END IF;',
'    END LOOP;',
'',
unistr('    -- Necess\00E1rio para disparar o envio do APEX_MAIL'),
'    APEX_MAIL.PUSH_QUEUE;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
/
