'    INTO l_blob, l_mime, l_filename',
'    FROM apex_application_temp_files',
'    WHERE name = :P3_IMAGEM;',
'',
'    INSERT INTO aniv_mensagem (',
'        imagem,',
'        mimetype,',
'        filename,',
'        nome',
'    ) VALUES (',
'        l_blob,',
'        l_mime,',
'        l_filename,',
'        :P3_NOME',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>364936310082194775
);
