,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Adicionar Anivers\00E1rio')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_email VARCHAR2(200);',
'BEGIN',
'    SELECT u.txt_email_sf INTO l_email',
'    FROM dda.usuario_rede u',
'    JOIN dda.vinculo_sf vs ON u.num_cpf_pessoa = vs.num_cpf',
'    WHERE vs.ind_vinculo_ativo = ''S''',
'        AND u.nom_situacao_login_ad = ''ATIVO''',
'        AND LOWER(',
'             TRANSLATE(',
'                 vs.nom_pessoa,',
unistr('                 ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                 ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''',
'             )',
'           ) =',
'           LOWER(',
'             TRANSLATE(',
'                 :P4_NOM_ANIV,',
unistr('                 ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                 ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''',
'             )',
'           );',
'',
'    INSERT INTO aniv_aniversarios (',
'        nom_aniv,',
'        dat_aniv,',
'        email,',
'        tel_aniv,',
'        dat_vinculo',
'    ) VALUES (',
'        :P4_NOM_ANIV,',
'        :P4_DAT_ANIV,',
'        l_email,',
'        :P4_TEL_ANIV,',
'        :P4_DAT_VINCULO',
'    );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>364032159253055918
);
end;
